import { trustOperatorConfiguredVeryfrontApiOrigins } from "../../../src/security/http/outbound-fetch.js";
/*******************************
 * Main init command implementation
 * @module
 *******************************/
import { cliLogger as logger, isVerbose } from "../../utils/index.js";
import { brand, dim } from "../../ui/index.js";
import { createTransientSpinner } from "../../ui/progress.js";
import { INVALID_ARGUMENT } from "../../../src/errors/index.js";
import { cwd } from "../../../src/platform/index.js";
import { getDlxCommand, getInstallCommand, getRunCommand } from "../../utils/package-manager.js";
import { createProject, } from "../../shared/project-creation.js";
import { validateProjectName } from "../../shared/project-name.js";
import { promptForEnvVars } from "../../utils/env-prompt.js";
import { runInteractiveWizard, shouldRunWizard } from "./interactive-wizard.js";
import { isTTY } from "../../utils/index.js";
import { isInteractive } from "../../shared/interactive.js";
import { chooseCloudProject } from "../../shared/cloud-project.js";
import { DEFAULT_TEMPLATE } from "./catalog.js";
const AUTH_REQUIRED_DEPLOY_MESSAGE = "Authentication required for --deploy.";
const DEPLOYMENT_FAILED_MESSAGE = "Deployment failed. Your project was created locally; run veryfront deploy from the project directory after reviewing your credentials and deployment settings.";
function safeDeploymentFailureMessage(error) {
    if (error instanceof Error && error.message === AUTH_REQUIRED_DEPLOY_MESSAGE) {
        return AUTH_REQUIRED_DEPLOY_MESSAGE;
    }
    return DEPLOYMENT_FAILED_MESSAGE;
}
const STRUCTURE_ORDER = [
    "app",
    "pages",
    "agents",
    "tools",
    "workflows",
    "tasks",
    "prompts",
    "resources",
    "skills",
    "components",
    "lib",
    "content",
    "AGENTS.md",
    "README.md",
    "package.json",
    "deno.json",
    "tsconfig.json",
    ".env",
    ".env.example",
    ".gitignore",
];
function structureRank(name) {
    const index = STRUCTURE_ORDER.indexOf(name);
    return index === -1 ? STRUCTURE_ORDER.length : index;
}
function compareCodeUnits(left, right) {
    if (left < right)
        return -1;
    if (left > right)
        return 1;
    return 0;
}
function sortStructureEntries([nameA, nodeA], [nameB, nodeB]) {
    const rankDiff = structureRank(nameA) - structureRank(nameB);
    if (rankDiff !== 0)
        return rankDiff;
    if (nodeA.file !== nodeB.file)
        return nodeA.file ? 1 : -1;
    return compareCodeUnits(nameA, nameB);
}
function renderProjectStructure(rootName, paths, maxLines = 22) {
    const root = { file: false, children: new Map() };
    const normalizedPaths = [...new Set(paths)]
        .filter((path) => path && !path.endsWith("/"))
        .sort(compareCodeUnits);
    for (const path of normalizedPaths) {
        const parts = path.split("/").filter(Boolean);
        let current = root;
        for (const [index, part] of parts.entries()) {
            const isFile = index === parts.length - 1;
            let child = current.children.get(part);
            if (!child) {
                child = { file: isFile, children: new Map() };
                current.children.set(part, child);
            }
            if (isFile)
                child.file = true;
            current = child;
        }
    }
    const lines = [`${rootName}/`];
    let omitted = 0;
    function walk(node, depth) {
        const entries = [...node.children.entries()].sort(sortStructureEntries);
        for (const [name, child] of entries) {
            if (lines.length >= maxLines) {
                omitted++;
                continue;
            }
            lines.push(`${"  ".repeat(depth)}${name}${child.file ? "" : "/"}`);
            if (!child.file)
                walk(child, depth + 1);
        }
    }
    walk(root, 1);
    if (omitted > 0) {
        lines.push(`${"  ".repeat(1)}... ${omitted} more ${omitted === 1 ? "entry" : "entries"}`);
    }
    return lines;
}
function validateInitProjectName(name) {
    const pathError = validateProjectName(name);
    if (pathError)
        return pathError;
    if (!/^[a-z0-9.-]+$/.test(name)) {
        return "Project name must use lowercase letters, numbers, dots, and hyphens";
    }
    return null;
}
/**
 * Initializes a new Veryfront project with the specified template
 */
export async function initCommand(options, dependencies = {}) {
    trustOperatorConfiguredVeryfrontApiOrigins();
    const { name, quiet = false } = options;
    const { integrations = [] } = options;
    const parentDir = options.parentDir ?? cwd();
    function log(msg) {
        if (!quiet)
            logger.info(msg);
    }
    let template;
    let projectName = name;
    let initGit = options.initGit ?? false;
    // Validate project name before doing anything else
    if (name) {
        const nameError = validateInitProjectName(name);
        if (nameError) {
            throw INVALID_ARGUMENT.create({ detail: nameError });
        }
    }
    let wizardRuntime = "node";
    const shouldStartWizard = dependencies.shouldRunWizard ?? shouldRunWizard;
    const runWizard = dependencies.runWizard ?? runInteractiveWizard;
    if (shouldStartWizard(options)) {
        const wizardResult = await runWizard(name, options.runtime);
        if (wizardResult.cancelled) {
            return { cancelled: true };
        }
        template = wizardResult.template;
        if (wizardResult.projectName) {
            projectName = wizardResult.projectName;
        }
        initGit = wizardResult.initGit;
        wizardRuntime = wizardResult.runtime;
    }
    else {
        template = options.template ?? DEFAULT_TEMPLATE;
    }
    if (projectName) {
        const nameError = validateInitProjectName(projectName);
        if (nameError) {
            throw INVALID_ARGUMENT.create({ detail: nameError });
        }
    }
    const runtime = options.runtime ?? wizardRuntime;
    // Whether the target can be written to is `createProject`'s call: it knows
    // which files the template ships, so it refuses exactly the files it would
    // overwrite rather than any directory that happens to exist.
    let installSpinner = null;
    const installObserver = {
        onEvent(event) {
            if (event.kind === "dependency-installation-started") {
                installSpinner = quiet
                    ? null
                    : createTransientSpinner(`Installing dependencies with ${event.packageManager}...`);
                return;
            }
            if (event.status === "installed") {
                installSpinner?.success("Dependencies installed");
                return;
            }
            installSpinner?.error("Dependency installation failed");
            if (!quiet) {
                logger.warn(`Run '${getInstallCommand(event.packageManager)}' manually to install dependencies.`);
            }
        },
    };
    const result = await createProject({
        name: projectName,
        parentDir,
        template,
        runtime,
        integrations,
        environmentValues: options.env ?? {},
        conflictPolicy: options.force ? "overwrite" : "fail",
        installDependencies: !options.skipInstall,
        initializeGit: initGit,
        includePackageMetadata: options.includePackageMetadata ?? !quiet,
    }, {
        observer: installObserver,
        beforeGitInitialization: async (projectDir) => {
            if (!quiet && !options.deploy && isTTY() && isInteractive()) {
                try {
                    await chooseCloudProject(projectDir);
                }
                catch (error) {
                    log(`  Cloud setup could not finish: ${error instanceof Error ? error.message : "Unknown error"}`);
                    log("  Your local project is ready. Run veryfront push to create or link a Cloud project later.");
                }
            }
        },
        resolveEnvironmentFiles: (variables, values) => promptForEnvVars(variables, {
            skipPrompt: options.skipEnvPrompt,
            prefilledValues: values,
        }),
    });
    if (result.gitInitialization === "failed" && !quiet) {
        logger.warn("Git initialization failed");
    }
    const createdProjectDir = result.projectDir;
    // Deploy to cloud if --deploy flag is set
    let deployedUrl;
    let deployment = { status: "skipped" };
    const manualDeployCommand = quiet
        ? `${getDlxCommand(result.packageManager)} veryfront deploy`
        : getRunCommand(result.packageManager, "deploy");
    if (options.deploy) {
        const manualDeployHint = `Run ${brand(manualDeployCommand)} to deploy later.`;
        if (dependencies.deployProject) {
            try {
                deployedUrl = await dependencies.deployProject(createdProjectDir);
                if (!deployedUrl) {
                    throw new Error("Deploy completed without a verified result.");
                }
                deployment = { status: "deployed", url: deployedUrl };
            }
            catch (error) {
                const message = safeDeploymentFailureMessage(error);
                deployment = { status: "failed", message };
                if (!quiet)
                    console.log();
                log(`  Deploy failed: ${message}`);
                log(`  Your project was created locally. ${manualDeployHint}`);
            }
        }
        else {
            const { chdir } = await import("../../../src/platform/compat/process/lifecycle.js");
            const { ensureAuthenticated } = await import("../../auth/index.js");
            const { deployCommand } = await import("../deploy/index.js");
            const authResult = await ensureAuthenticated(undefined, createdProjectDir);
            if (!authResult) {
                deployment = { status: "failed", message: AUTH_REQUIRED_DEPLOY_MESSAGE };
                if (!quiet)
                    console.log();
                log(`  Authentication required for --deploy. ${manualDeployHint}`);
            }
            else {
                if (!quiet)
                    console.log();
                log(`  Deploying project...`);
                const previousDir = cwd();
                try {
                    chdir(createdProjectDir);
                    const deployResult = await deployCommand({
                        projectDir: createdProjectDir,
                        branch: "main",
                        env: "production",
                        force: true,
                        dryRun: false,
                        quiet: true,
                        suppressJsonOutput: true,
                    });
                    if (!deployResult) {
                        throw new Error("Deploy completed without a verified result.");
                    }
                    deployedUrl = deployResult.url;
                    deployment = { status: "deployed", url: deployedUrl };
                }
                catch (error) {
                    const message = safeDeploymentFailureMessage(error);
                    deployment = { status: "failed", message };
                    if (!quiet)
                        console.log();
                    log(`  Deploy failed: ${message}`);
                    log(`  Your project was created locally. ${manualDeployHint}`);
                }
                finally {
                    chdir(previousDir);
                }
            }
        }
    }
    // Build success box with next steps
    const pm = result.packageManager;
    const devCommand = getRunCommand(pm, "dev");
    const localSteps = [];
    if (projectName) {
        localSteps.push(`cd ${projectName}`);
    }
    if (options.skipInstall) {
        localSteps.push(getInstallCommand(pm));
    }
    localSteps.push(devCommand);
    const displayName = projectName ?? "Project";
    const structureRoot = projectName ?? ".";
    const structureLines = renderProjectStructure(structureRoot, result.createdPaths);
    const deployCommandHint = getRunCommand(pm, "deploy");
    if (!quiet) {
        console.log();
        console.log(`  ✓ ${displayName} ready`);
        if (isVerbose()) {
            console.log();
            console.log("  Project structure");
            for (const line of structureLines) {
                console.log(`  ${line}`);
            }
        }
        console.log();
        for (const [index, step] of localSteps.entries()) {
            console.log(`  ${index === 0 ? brand(step) : step}`);
        }
        if (deployedUrl) {
            console.log();
            console.log(`  Live: ${brand(deployedUrl)}`);
        }
        else {
            console.log();
            console.log(`  Deploy: ${brand(deployCommandHint)}`);
        }
        const tips = [];
        if (result.setupTips.length) {
            for (const tip of result.setupTips) {
                tips.push(dim(tip));
            }
        }
        if (tips.length) {
            console.log();
            for (const tip of tips) {
                console.log(`  ${tip}`);
            }
        }
        console.log();
    }
    return {
        cancelled: false,
        ...result,
        template,
        runtime,
        deployedUrl,
        deployment,
    };
}
